SELECT payment_key AS paymentKey
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}

SELECT s.student_id, s.student_name, pAgg.paymentKey, pAgg.hanFee, pAgg.bookFee, pAgg.hanMaterial, pAgg.bookMaterial, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, pAgg.totalPrice, pAgg.totalFee, pAgg.totalMaterialFee, (a.parent_tel_first + a.parent_tel_middle + a.parent_tel_last) AS parentPhone, subj.subject, bill.eduStatus, bill.materialStatus FROM erp_student s JOIN erp_parent a ON s.student_id = a.student_id JOIN ( SELECT p.student_id, p.payment_key AS paymentKey, MAX(CASE WHEN d.class_type = 1 AND d.item_type = 'edu' THEN d.amount END) AS hanFee, MAX(CASE WHEN d.class_type = 2 AND d.item_type = 'edu' THEN d.amount END) AS bookFee, MAX(CASE WHEN d.class_type = 1 AND d.item_type = 'book' THEN d.amount END) AS hanMaterial, MAX(CASE WHEN d.class_type = 2 AND d.item_type = 'book' THEN d.amount END) AS bookMaterial, MAX(CASE WHEN d.class_type = 1 THEN d.user_code END) AS hanUserCode, MAX(CASE WHEN d.class_type = 2 THEN d.user_code END) AS bookUserCode, SUM(d.amount) AS totalPrice, SUM(CASE WHEN d.item_type = 'edu' THEN d.amount ELSE 0 END) AS totalFee, SUM(CASE WHEN d.item_type = 'book' THEN d.amount ELSE 0 END) AS totalMaterialFee FROM erp_payment p JOIN erp_payment_detail d ON p.payment_key = d.payment_key WHERE p.yy = #{year} AND p.mm = #{month} GROUP BY p.student_id, p.payment_key ) AS pAgg ON pAgg.student_id = s.student_id LEFT JOIN erp_user hu ON pAgg.hanUserCode = hu.user_code LEFT JOIN erp_user bu ON pAgg.bookUserCode = bu.user_code OUTER APPLY ( SELECT MAX(CASE WHEN pb.bill_type = 'edu' THEN pb.status END) AS eduStatus, MAX(CASE WHEN pb.bill_type = 'material' THEN pb.status END) AS materialStatus FROM erp_payment_bill pb WHERE pb.payment_key = pAgg.paymentKey ) bill OUTER APPLY ( SELECT STUFF(( SELECT ', ' + c.class_name FROM erp_time_table_assign ta JOIN erp_time_table t ON ta.time_table_key = t.time_table_key JOIN erp_class_code c ON c.class_key = CASE WHEN t.class_key = 'COM' THEN ta.class_key ELSE t.class_key END WHERE ta.student_id = s.student_id AND c.class_type IN (1, 2) AND t.yy = #{year} AND t.mm = #{month}
AND t.user_code = #{userCode}
ORDER BY c.class_type ASC FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, '') AS subject) subj WHERE EXISTS ( SELECT 1 FROM erp_time_table_assign ta JOIN erp_time_table t ON ta.time_table_key = t.time_table_key WHERE ta.student_id = s.student_id AND t.yy = #{year} AND t.mm = #{month}
AND t.user_code = #{userCode} );

SELECT fee
FROM ERP_CLASS_FEE_MAP
WHERE class_key = #{classKey}
  AND center_code = #{centerCode}

SELECT TOP 1 payment_key
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
ORDER BY created_at DESC

